test("macOS で動いているとき、コマンドキー付きの割り当ては ⌘C と綴る", () => {
  expect(
    ShownShortcut.toText(
      { kind: "command", key: "C", withShiftKey: false },
      MacOs,
    ),
  ).toBe("⌘C");
});

test("macOS で動いているとき、Shift とコマンドキー付きの割り当ては Shift+⌘G と綴る", () => {
  expect(
    ShownShortcut.toText(
      { kind: "command", key: "G", withShiftKey: true },
      MacOs,
    ),
  ).toBe("Shift+⌘G");
});

test("Windows で動いているとき、コマンドキー付きの割り当ては Ctrl+C と綴る", () => {
  expect(
    ShownShortcut.toText(
      { kind: "command", key: "C", withShiftKey: false },
      Windows,
    ),
  ).toBe("Ctrl+C");
});

test("Linux で動いているとき、コマンドキー付きの割り当ては Ctrl+C と綴る", () => {
  expect(
    ShownShortcut.toText(
      { kind: "command", key: "C", withShiftKey: false },
      Linux,
    ),
  ).toBe("Ctrl+C");
});

test("Windows・Linux で動いているとき、Shift とコマンドキー付きの割り当ては Ctrl を先にして Ctrl+Shift+G と綴る", () => {
  expect(
    ShownShortcut.toText(
      { kind: "command", key: "G", withShiftKey: true },
      Windows,
    ),
  ).toBe("Ctrl+Shift+G");
});

test("修飾の無い割り当ては、macOS でもキーの綴りのまま出る", () => {
  expect(ShownShortcut.toText({ kind: "plain", key: "Delete" }, MacOs)).toBe(
    "Delete",
  );
});

test("修飾の無い割り当ては、Windows でもキーの綴りのまま出る", () => {
  expect(ShownShortcut.toText({ kind: "plain", key: "Delete" }, Windows)).toBe(
    "Delete",
  );
});

/*
 * 割り当ては説明の末尾に、前の文言と空白で区切って付く。区切りから末尾までを割り当ての綴りと
 * 突き合わせ、`Shift+⌘O` のように前へ修飾が付いた綴りを通さない。
 */
test("macOS で動いているとき、開くボタンには、⌘O でも開けることが説明として添えられる", () => {
  renderDocumentStart({
    operatingSystem: OperatingSystem.fromNavigator(MacOsNavigatorPlatform),
  });

  expect(
    screen.getByRole("button", { name: "開く", description: /(?:^|\s)⌘O$/ }),
  ).toBeDefined();
});

test("macOS で動いているとき、新規作成ボタンには、⌘N でも作れることが説明として添えられる", () => {
  renderDocumentStart({
    operatingSystem: OperatingSystem.fromNavigator(MacOsNavigatorPlatform),
  });

  expect(
    screen.getByRole("button", {
      name: "新規作成",
      description: /(?:^|\s)⌘N$/,
    }),
  ).toBeDefined();
});

test("Windows で動いているとき、開くボタンには、Ctrl+O でも開けることが説明として添えられる", () => {
  renderDocumentStart({
    operatingSystem: OperatingSystem.fromNavigator(WindowsNavigatorPlatform),
  });

  expect(
    screen.getByRole("button", {
      name: "開く",
      description: /(?:^|\s)Ctrl\+O$/,
    }),
  ).toBeDefined();
});

test("Windows で動いているとき、新規作成ボタンには、Ctrl+N でも作れることが説明として添えられる", () => {
  renderDocumentStart({
    operatingSystem: OperatingSystem.fromNavigator(WindowsNavigatorPlatform),
  });

  expect(
    screen.getByRole("button", {
      name: "新規作成",
      description: /(?:^|\s)Ctrl\+N$/,
    }),
  ).toBeDefined();
});

test("Windows で動いているとき、開くボタンの説明に ⌘ は出ない", () => {
  renderDocumentStart({
    operatingSystem: OperatingSystem.fromNavigator(WindowsNavigatorPlatform),
  });

  const openButton = screen.getByRole("button", { name: "開く" });
  expect(openButton.textContent).not.toContain("⌘");
});

/**
 * その OS で動いていることにして、何も開いていない画面の開くカードを引く。
 *
 * @param navigatorPlatform アプリが動いている webview の `navigator`
 * @returns 開始画面の開くカード
 */
function openCardOn(navigatorPlatform: NavigatorPlatform): HTMLElement {
  renderEditorScreen(
    {},
    { open: DialogChoice.Canceled, save: DialogChoice.Canceled },
    { navigatorPlatform },
  );

  return screen.getByRole("button", { name: "開く" });
}

test("Windows で動いている画面で何も開いていないとき、開始画面の開くカードに Ctrl+O が添えられる", () => {
  const openCard = openCardOn(WindowsNavigatorPlatform);

  expect(within(openCard).getByText("Ctrl+O")).toBeDefined();
});

test("macOS で動いている画面で何も開いていないとき、開始画面の開くカードに ⌘O が添えられる", () => {
  const openCard = openCardOn(MacOsNavigatorPlatform);

  expect(within(openCard).getByText("⌘O")).toBeDefined();
});

test("Windows で動いている画面でドキュメントを開くと、ツリーの行のメニューの Copy に Ctrl+C が併記される", async () => {
  const copyRow = await copyRowOn(WindowsNavigatorPlatform);

  expect(copyRow.textContent).toContain("Ctrl+C");
});

